/* Spotify DNA — near-black entertainment surface, vivid green, pills everywhere */
.theme-spotify-dna {
  --bg: oklch(0.182 0 0);
  --surface: oklch(0.235 0 0);
  --surface-2: oklch(0.277 0 0);
  --fg: oklch(0.985 0 0);
  --fg-muted: oklch(0.767 0 0);
  --accent: oklch(0.689 0.187 148.9);
  --accent-fg: oklch(0.14 0 0);
  --accent-2: oklch(0.65 0.2 300);
  --line: oklch(1 0 0 / 12%);
  --success: oklch(0.689 0.187 148.9);
  --warning: oklch(0.83 0.16 85);
  --danger: oklch(0.65 0.22 25);

  --radius: 0.5rem;
  --radius-sm: 0.375rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 2px 6px oklch(0 0 0 / 50%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 60%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 70%);
  --glow: 0 0 0 2px color-mix(in oklab, var(--accent) 60%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "DM Sans", "Inter", sans-serif;
  --font-body: "DM Sans", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.035em;
  --label-transform: uppercase;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  background-image: linear-gradient(180deg, oklch(0.24 0.05 148 / 45%) 0%, transparent 520px);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-spotify-dna h1,
.theme-spotify-dna h2,
.theme-spotify-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 800;
}

.theme-spotify-dna button {
  border-radius: var(--radius-pill);
  font-weight: 700;
  transition: transform 120ms ease, filter 120ms ease;
}

.theme-spotify-dna button:hover {
  transform: scale(1.04);
}

/* signature */
.theme-spotify-dna { --font-ui: var(--font-display); }
.theme-spotify-dna h1 { font-weight: 900; letter-spacing: -0.05em; }
.theme-spotify-dna button { text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.8em; }

/* alt mode: auto-derived light variant */
.theme-spotify-dna.alt-mode {
  --bg: oklch(0.98 0.000 0.0);
  --surface: oklch(0.955 0.000 0.0);
  --surface-2: oklch(0.92 0.000 0.0);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
